import networkx as nx

def check_graph(edges):
    G = nx.Graph()
    G.add_nodes_from(range(12))
    G.add_edges_from(edges)

    # Check fixed edges
    fixed_edges = [(1,2), (0,2), (1,4), (2,9), (2,7)]
    for edge in fixed_edges:
        if not G.has_edge(*edge):
            return False, "Missing fixed edge"

    # Check degree >= 3
    for i in range(12):
        if G.degree(i) < 3:
            return False, f"Vertex {i} has degree {G.degree(i)}"

    # Check max clique size <= 5
    clique_size = nx.graph_clique_number(G)
    if clique_size > 5:
        return False, f"Clique size is {clique_size}"

    # Check chromatic number <= 3
    # nx.coloring.greedy_color(G) gives an upper bound.
    # For exact chromatic number, use nx.coloring.greedy_color with strategy
    # or just check if it's 3-colorable.
    # Since it's 12 vertices, we can use nx.coloring.greedy_color
    # but that's not guaranteed to be the chromatic number.
    # Let's use a backtracking approach to check 3-colorability.

    def is_3_colorable(G):
        coloring = {}
        def solve(node):
            if node == 12:
                return True
            for color in range(3):
                can_color = True
                for neighbor in G.neighbors(node):
                    if neighbor in coloring and coloring[neighbor] == color:
                        can_color = False
                        break
                if can_color:
                    coloring[node] = color
                    if solve(node + 1):
                        return True
                    del coloring[node]
            return False
        return solve(0)

    if not is_3_colorable(G):
        return False, "Not 3-colorable"

    return True, "Valid"

